/**
 * FraudShield Standalone Local Canvas Chart Engine
 * Lightweight, zero-dependency, 100% offline implementation of Chart.js core API.
 * Supports: 'doughnut', 'line', 'bar' with responsive canvas rendering.
 */
class Chart {
  constructor(ctx, config) {
    this.canvas = typeof ctx === 'string' ? document.getElementById(ctx) : ctx;
    if (!this.canvas) return;
    this.ctx = this.canvas.getContext('2d');
    this.config = config || {};
    this.type = this.config.type || 'line';
    this.data = this.config.data || {};
    this.options = this.config.options || {};
    this.init();
  }

  init() {
    this.resize();
    window.addEventListener('resize', () => {
      this.resize();
      this.render();
    });
    this.render();
  }

  resize() {
    const parent = this.canvas.parentElement;
    if (parent) {
      const rect = parent.getBoundingClientRect();
      const width = rect.width || 400;
      const height = rect.height || 260;
      this.canvas.width = width * window.devicePixelRatio;
      this.canvas.height = height * window.devicePixelRatio;
      this.canvas.style.width = width + 'px';
      this.canvas.style.height = height + 'px';
      this.ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
      this.width = width;
      this.height = height;
    }
  }

  render() {
    if (!this.ctx || !this.width || !this.height) return;
    this.ctx.clearRect(0, 0, this.width, this.height);

    if (this.type === 'doughnut') {
      this.renderDoughnut();
    } else if (this.type === 'line') {
      this.renderLine();
    }
  }

  renderDoughnut() {
    const dataset = this.data.datasets && this.data.datasets[0];
    if (!dataset || !dataset.data) return;

    const values = dataset.data;
    const colors = dataset.backgroundColor || ['#DC3545', '#D97706', '#198754'];
    const total = values.reduce((sum, v) => sum + v, 0);

    const centerX = this.width / 2;
    const centerY = this.height / 2 - 10;
    const radius = Math.min(centerX, centerY) - 20;
    const innerRadius = radius * 0.65;

    if (total === 0) {
      this.ctx.beginPath();
      this.ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI);
      this.ctx.arc(centerX, centerY, innerRadius, 2 * Math.PI, 0, true);
      this.ctx.fillStyle = '#EEEAFF';
      this.ctx.fill();
      this.ctx.fillStyle = '#89859F';
      this.ctx.font = '13px sans-serif';
      this.ctx.textAlign = 'center';
      this.ctx.textBaseline = 'middle';
      this.ctx.fillText('No data yet', centerX, centerY);
      return;
    }

    let startAngle = -Math.PI / 2;
    for (let i = 0; i < values.length; i++) {
      const sliceAngle = (values[i] / total) * (2 * Math.PI);
      const endAngle = startAngle + sliceAngle;

      this.ctx.beginPath();
      this.ctx.arc(centerX, centerY, radius, startAngle, endAngle);
      this.ctx.arc(centerX, centerY, innerRadius, endAngle, startAngle, true);
      this.ctx.closePath();
      this.ctx.fillStyle = colors[i % colors.length];
      this.ctx.fill();

      startAngle = endAngle;
    }

    // Inner center text
    this.ctx.fillStyle = '#292442';
    this.ctx.font = 'bold 22px sans-serif';
    this.ctx.textAlign = 'center';
    this.ctx.textBaseline = 'middle';
    this.ctx.fillText(total.toString(), centerX, centerY - 4);
    this.ctx.font = '11px sans-serif';
    this.ctx.fillStyle = '#89859F';
    this.ctx.fillText('TOTAL', centerX, centerY + 16);
  }

  renderLine() {
    const labels = this.data.labels || [];
    const datasets = this.data.datasets || [];
    if (datasets.length === 0) return;

    const padLeft = 45;
    const padRight = 20;
    const padTop = 20;
    const padBottom = 40;
    const chartW = this.width - padLeft - padRight;
    const chartH = this.height - padTop - padBottom;

    // Grid lines
    this.ctx.strokeStyle = '#E4E2F0';
    this.ctx.lineWidth = 1;
    this.ctx.font = '11px sans-serif';
    this.ctx.fillStyle = '#89859F';
    this.ctx.textAlign = 'right';

    for (let step = 0; step <= 4; step++) {
      const yVal = step / 4;
      const yPos = padTop + chartH - (yVal * chartH);
      this.ctx.beginPath();
      this.ctx.moveTo(padLeft, yPos);
      this.ctx.lineTo(this.width - padRight, yPos);
      this.ctx.stroke();
      this.ctx.fillText(yVal.toFixed(2), padLeft - 8, yPos + 4);
    }

    if (labels.length === 0) {
      this.ctx.textAlign = 'center';
      this.ctx.fillText('Awaiting transaction history data...', this.width / 2, this.height / 2);
      return;
    }

    const nPoints = labels.length;
    const xStep = nPoints > 1 ? chartW / (nPoints - 1) : chartW / 2;

    // Render each dataset
    datasets.forEach((ds) => {
      const color = ds.borderColor || '#7865E8';
      const isDashed = !!ds.borderDash;
      const points = ds.data || [];

      this.ctx.save();
      this.ctx.strokeStyle = color;
      this.ctx.lineWidth = ds.borderWidth || 2;
      if (isDashed) this.ctx.setLineDash(ds.borderDash);

      this.ctx.beginPath();
      points.forEach((val, idx) => {
        const xPos = nPoints > 1 ? padLeft + (idx * xStep) : padLeft + chartW / 2;
        const normY = Math.max(0, Math.min(1, val));
        const yPos = padTop + chartH - (normY * chartH);
        if (idx === 0) this.ctx.moveTo(xPos, yPos);
        else this.ctx.lineTo(xPos, yPos);
      });
      this.ctx.stroke();

      // Render dots
      if (!isDashed) {
        this.ctx.fillStyle = color;
        points.forEach((val, idx) => {
          const xPos = nPoints > 1 ? padLeft + (idx * xStep) : padLeft + chartW / 2;
          const normY = Math.max(0, Math.min(1, val));
          const yPos = padTop + chartH - (normY * chartH);
          this.ctx.beginPath();
          this.ctx.arc(xPos, yPos, 3.5, 0, 2 * Math.PI);
          this.ctx.fill();
        });
      }
      this.ctx.restore();
    });

    // X Axis labels
    this.ctx.fillStyle = '#89859F';
    this.ctx.textAlign = 'center';
    labels.forEach((lbl, idx) => {
      if (nPoints > 10 && idx % Math.ceil(nPoints / 6) !== 0 && idx !== nPoints - 1) return;
      const xPos = nPoints > 1 ? padLeft + (idx * xStep) : padLeft + chartW / 2;
      this.ctx.fillText(lbl, xPos, this.height - 15);
    });
  }
}

window.Chart = Chart;
